    return ADCS_E_NULL;
}

if (!adcs_is_finite_vec3(raw_t)) {
    finite = 0;
}
if (!adcs_is_finite_vec3(bias_t)) {
    finite = 0;
}
for (i = 0; i < 3; i++) {
    for (j = 0; j < 3; j++) {
        if (!isfinite(calibration->m[i][j])) {
            finite = 0;
        }
    }
}
