    corrected_t->x = 0.0;
    corrected_t->y = 0.0;
    corrected_t->z = 0.0;
    return ADCS_E_NOT_FINITE;
}

delta = adcs_vec3_sub(raw_t, bias_t);
*corrected_t = adcs_mat3_mul_vec(calibration, &delta);

return ADCS_OK;
}

